const stdout = $input.first().json.stdout;
let result;

try {
  result = JSON.parse(stdout);
} catch (e) {
  result = { error: 'Failed to parse script output: ' + e.message, removed: [], count: 0 };
}

if (result.error) {
  return [{
    json: {
      count: 1,
      error: result.error,
      discordPayload: {
        embeds: [{
          title: 'Tracker Deleted Cleanup Error',
          description: result.error,
          color: 15158332,
          timestamp: new Date().toISOString(),
          footer: { text: 'Tracker Deleted Cleanup Automation' }
        }]
      }
    }
  }];
}

const fields = (result.removed || []).map(t => ({
  name: String(t.name || 'Unknown').slice(0, 256),
  value: ('ID ' + t.id + ' | ' + t.percentDone + '% complete | ' + (t.label || 'unlabeled') + '\n' + (t.match || '')).slice(0, 1024),
  inline: false
}));

const embed = {
  title: 'Tracker Deleted Cleanup',
  description: 'Removed **' + result.count + '** torrent(s)' + (result.deleteLocalData ? ' with local data deletion' : ''),
  color: 16744576,
  fields: fields.slice(0, 25),
  timestamp: new Date().toISOString(),
  footer: { text: 'Tracker Deleted Cleanup Automation' }
};

return [{
  json: {
    count: result.count,
    removed: result.removed,
    discordPayload: { embeds: [embed] }
  }
}];
